class cu(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2
    lookup_handler, store = aliasing_scope(lookup_arg='coam', lookup_type=Coam)

    def __init__(self):
        self.page = None
        self.__driver = None
        self._download_dir = None
        self._tmp_download_dir = False
        self._display = None
        self.__debug_dir = None
        self.browser = None
        self.is_headless = False
        self.downloader = Downloader()

    def _create_driver(self):
        if self.browser == "Chrome":
            driver = CustomWebDriverChrome(self.download_dir, self.is_headless)
        else:
            driver = CustomWebDriverFirefox(self.download_dir)
            driver.maximize_window()
        return driver

    @property
    def download_dir(self):
        """ Get download directory path.
        If path was not provided, function returns path to temporary directory,
        which will be removed during logout. """
        return self.get_download_dir()

    def get_download_dir(self):
        """ Function for compatibility with robot framework.  See download_dir property. """
        if self._download_dir is None:
            self._download_dir = tempfile.mkdtemp(suffix="taf_selenium_cOAM_cu_debug")
        return self._download_dir

    def set_debug_dir(self, debug_dir):
        """
        Set debug directory path.

        :param debug_dir: path to download dir
        """
        self.__debug_dir = debug_dir
        if not os.path.exists(self.__debug_dir):
            os.makedirs(self.__debug_dir)

    @download_dir.setter
    def download_dir(self, download_dir):
        """ Set download directory path.
        Note that this function can be called only before driver initialization.

        :param download_dir: path to download dir
        """
        self.set_debug_dir(download_dir)
        self.set_download_dir(download_dir)

    def set_download_dir(self, download_dir):
        """ Function for compatibility with robot framework. See download_dir property. """
        if self.__driver is None:
            self._download_dir = download_dir
        else:
            raise AttributeError("Download dir must be set before initialization of "
                                 "driver (in most cases before login keyword)")

    @property
    def _debug_dir(self):
        return self.get_debug_dir()

    def get_debug_dir(self):
        """
        Get debug directory path.
        """
        if self.__debug_dir is None:
            self.__debug_dir = tempfile.mkdtemp(prefix="taf_selenium_cOAM_cu_debug")
        return self.__debug_dir

    @_debug_dir.setter
    def _debug_dir(self, download_dir):
        self.set_download_dir(download_dir)

    def enable_virtual_display(self, width=1920, height=1280):
        """
        This keyword is used to enable virtual display - with it enabled browser
        window will not be displayed on screen.

        In order for this functionality to work correctly this keyword must to be
        called before `Login` keyword is called (which would spawn browser window).

        Please make sure "xvfb" service is installed on the environment.

        :param width: int, width of browser
        :param height: int, height of browser
        """
        self._display = Display(visible=0, size=(width, height))
        self._display.start()

    def disable_virtual_display(self):
        """
        This keyword is used to disable virtual display.
        Please make sure to call this method at the end of test.py if you've call "enable_virtual_display"
        """
        self._display.stop()

    def _configure_before_login(self, version):
        driver = self._create_driver()
        coam_cls = Provider.provide(version)
        coam_instance = coam_cls(driver)
        return coam_instance

    def login(self, url, username="Nemuadmin", password="nemuuser", read_only_user=False, browser="Chrome",
              is_headless=False, timeout=60, coam=None, version="COAM26R1"):
        """
        Login into coam cu WebEM as Web Element Manager.

        :param url: str, url to coam cu WebEM
        :param username: str, username
        :param password: str, password
        :param read_only_user boolean, read only user checkbox
        :param browser: str, Default browser will be "Chrome", if user wants it to run via from Firefox
                            then change the browser parameter to "Firefox"
        :param is_headless: Boolean, Decide to run in browser head less mode or not, default is False
        :param timeout: int, timeout for the element be available to click
        :param coam: str, (optional) alias that the new coam cu object will be identified by
                        If not specified, default alias is used: "None"
        :param version: str, (optional) version of coam_cu, default is "coam26r1"

        """
        self.is_headless = is_headless
        self.browser = browser
        coam_instance = self._configure_before_login(version)
        login_banner = coam_instance.login(url, username, password, read_only_user, int(timeout))
        self.store.add(coam_instance, coam)
        self.lookup_handler.store = self.store
        return login_banner

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def logout(self, timeout=60, coam=None):

        """
        Logout from coam cu web.

        :param timeout: int, timeout for the element be available to click
        :param coam:  str, (optional) alias that the new coam cu object will be identified by
                        If not specified, default alias is used: "None"
        """
        coam.logout(int(timeout))
        self.store.remove_object(coam)

