    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def save_bts_configuration(self, save_configuration_type=0, coam=None):
        """
        Keyword for saving bts configuration
        To save bts config first you have to choose scf file.Use "choose_plan" keyword to choose the scf file
        and then use save_bts_configuration keyword.

        :param save_configuration_type: int, type of save type
                0: Save SCF - configuration only
                1: Save delta SCF - delta configuration only
                2: Save BTS runtime information only
        :param coam:  str, (optional) alias that the new coam cu object will be identified by
                        If not specified, default alias is used: "None"

        Note: Starting from feature CB012840, the save_configuration_type parameter will be defined as follows
        :param save_configuration_type: str, list of save type. example: BTS configuration,BTS runtime configuration
                - BTS configuration
                - BTS runtime configuration
                - Planned parameter changes

        :return str, path to download configuration file
        """
        start_time = time.time()
        _save_bts_configuration_type_dict = {0: "Save SCF - configuration only",
                                             1: "Save delta SCF - delta configuration only",
                                             2: "Save full runtime configuration"}
        if isinstance(save_configuration_type, int):
            coam.configuration.open_page_and_get_instance('Parameter Editor') \
                .save_bts_configuration(_save_bts_configuration_type_dict[int(save_configuration_type)])
        else:
            coam.configuration.open_page_and_get_instance('Parameter Editor') \
                .save_bts_configuration(save_configuration_type)
        return self.downloader.download(download_dir=self.download_dir,
                                        start_downloading_time=start_time)

