    def get_dus_status_info(self, timeout=60, coam=None):
        """
        Keyword for getting DUs information under DUs status page

        :param timeout: int, timeout for getting the status info
        :param coam:  str, (optional) alias that the new coam cu object will be identified by
                        If not specified, default alias is used: "None"

        :return: dict, specific information of DUs
        """
        cell_id = []
        cell_info = coam.dashboard.open_page_and_get_instance('Dashboard'). \
            get_dus_cell_info(int(timeout))
        if int(cell_info) == 0:
            return "No DUs to display"
        else:
            for i in range(1, int(cell_info) + 1):
                cell = "NRDU-" + str(i)
                cell_id.append(cell)
            return coam.bts_status.open_page_and_get_instance('DUs Status'). \
                get_dus_status_info(get_info='DUs', cell_id=cell_id, timeout=int(timeout))

