    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def get_ng_links_status_info(self, timeout=60, coam=None):
        """
        This keyword will get the NG links status information.

        :param timeout: int, timeout for the element be available to click
        :param coam: str, (optional) alias that the new coam cu object will be identified by
                        If not specified, default alias is used: "None"

        :return: dict, specific information of the NG links status
        """
        cell_id = []
        cell_info = coam.dashboard.open_page_and_get_instance('Dashboard'). \
            get_ng_links_cell_info(int(timeout))
        if int(cell_info) == 0:
            return "No NG Links to display"
        else:
            for i in range(1, int(cell_info) + 1):
                cell = "SERVEDAMF-" + str(i)
                cell_id.append(cell)
        return coam.bts_status.open_page_and_get_instance('NG Links Status'). \
            get_dus_status_info(get_info='NG_Links_Status', cell_id=cell_id, timeout=int(timeout))
